const deacc = (s) => s.toLowerCase().normalize("NFD").replace(/[\\u0300-\\u036f]/g, "");
const ALIASES = {
  en: ["eng", "english", "anglais", "ingles"], fr: ["fre", "fra", "french", "francais"], es: ["spa", "esp", "spanish", "espanol", "castellano"],
  de: ["ger", "deu", "german", "deutsch"], it: ["ita", "italian", "italiano"], pt: ["por", "portuguese", "portugues"], ar: ["ara", "arabic", "arabe"],
  nl: ["dut", "nld", "dutch", "nederlands"], ru: ["rus", "russian"], zh: ["chi", "zho", "chinese", "mandarin"], ja: ["jpn", "japanese"],
  ko: ["kor", "korean"], tr: ["tur", "turkish"], pl: ["pol", "polish"], hi: ["hin", "hindi"],
