    const ng = Math.max(0, ...cfg.map((l) => lists[l.code].length));
    for (let gi = 0; gi < ng; gi++) {
      const nv = Math.max(0, ...cfg.map((l) => (lists[l.code][gi] ? lists[l.code][gi].videos.length : 0)));
      for (let vi = 0; vi < nv; vi++) {
        const e = { per: {}, titles: {} };
