const setStatus = (e, t, cls) => { if (e.statusEl) { e.statusEl.textContent = t; e.statusEl.className = "msg " + (cls || ""); } };

$("clear").onclick = () => { if (busy) return; cfg.forEach((l) => { sel[l.code] = { videos: [], images: [], subs: [], row: "" }; $("row_" + l.code).value = ""; $("sum_" + l.code).textContent = "Nothing selected"; }); plan = []; planNote = ""; planInfo = ""; skippedFmt = []; renderPlan(); say(""); };

/* ---------- uploading ---------- */
function makePoster(file) {
  return new Promise((resolve) => {
    const url = URL.createObjectURL(file), v = document.createElement("video");
    let done = false;
    const finish = (b) => { if (done) return; done = true; v.removeAttribute("src"); v.load(); URL.revokeObjectURL(url); resolve(b); };
    v.muted = true; v.playsInline = true; v.preload = "metadata"; v.src = url;
    v.onerror = () => finish(null);
    v.onloadedmetadata = () => { v.currentTime = Math.min(1, (v.duration || 1) / 2); };
    v.onseeked = () => {
      const c = document.createElement("canvas"); c.width = 1280; c.height = Math.round(1280 * v.videoHeight / v.videoWidth) || 720;
      c.getContext("2d").drawImage(v, 0, 0, c.width, c.height); c.toBlob((b) => finish(b), "image/jpeg", 0.85);
    };
    setTimeout(() => finish(null), 25000);
  });
}
async function api(path, key, body) {
  const r = await fetch(path, { method: "POST", headers: { "Content-Type": "application/json", "x-api-key": key }, body: JSON.stringify(body) });
  const data = await r.json().catch(() => ({}));
  if (!r.ok) throw new Error(r.status === 401 ? "Wrong upload key." : (data.error || "Request failed (" + r.status + ")."));
  return data;
}
