    x.onload = () => (x.status < 300 ? resolve(x.getResponseHeader("ETag")) : reject(new Error("Storage error " + x.status + ". Check the R2 keys and CORS policy.")));
    x.onerror = () => reject(new Error("Upload interrupted or blocked. Check your connection and the bucket CORS policy."));
    x.send(body);
  });
}
async function put(url, body, type, onBytes) {
