  function el(tag, cls, text) {
    var e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text) e.textContent = text;
    return e;
  }

  var languages = [], videos = [], lang = "";

  function firstOf(map) { // value in the visitor's language, else the first configured language that has one
    if (!map) return "";
    if (map[lang]) return map[lang];
    for (var i = 0; i < languages.length; i++) if (map[languages[i].code]) return map[languages[i].code];
    return "";
  }
  function versionFor(entry, code) {
    if (entry.versions[code]) return entry.versions[code];
    for (var i = 0; i < languages.length; i++) if (entry.versions[languages[i].code]) return entry.versions[languages[i].code];
  }
  function pickInitialLang() {
    var codes = languages.map(function (l) { return l.code; });
    var want = (script.dataset.lang || "").toLowerCase();
    if (codes.indexOf(want) > -1) return want;
    var prefs = navigator.languages || [navigator.language || ""];
    for (var i = 0; i < prefs.length; i++) {
      var p = prefs[i].toLowerCase();
