      t.addEventListener("error", function () { if (onError) onError(i); });
      video.appendChild(t);
    });
    return di;
  }

  function openPlayer(entry, opener) {
    var avail = languages.filter(function (l) { return entry.versions[l.code]; });
    var current = entry.versions[lang] ? lang : avail[0].code;
    var title = firstOf(entry.titles);

    var modal = el("div", "nf-modal");
    modal.setAttribute("role", "dialog"); modal.setAttribute("aria-modal", "true"); modal.setAttribute("aria-label", title);
    var dlg = el("div", "nf-dialog");
    var video = document.createElement("video");
    video.controls = true; video.autoplay = true; video.playsInline = true;
    var close = el("button", "nf-close", "\\u00d7");
    close.setAttribute("aria-label", "Close");
    var foot = el("div", "nf-foot");
    foot.appendChild(el("h4", "", title));
    var pills = el("div", "nf-langs"); pills.style.margin = "0";
    var subBar = el("div", "nf-langs"); subBar.style.margin = "0"; subBar.style.alignItems = "center";
    var extra = [], curVersion = null, pick = document.createElement("input");
    pick.type = "file"; pick.accept = ".srt,.vtt,text/vtt"; pick.style.display = "none";
    function showSub(i) {
      var tl = video.textTracks;
      for (var k = 0; k < tl.length; k++) tl[k].mode = k === i ? "showing" : "disabled";
      Array.prototype.forEach.call(subBar.querySelectorAll("button"), function (b) { if (b.getAttribute("data-i") !== null) b.setAttribute("aria-pressed", String(Number(b.getAttribute("data-i")) === i)); });
    }
    function markBad(i) {
      var b = subBar.querySelector('button[data-i="' + i + '"]');
      if (b) { b.textContent = b.textContent.split(" (")[0] + " (unavailable)"; b.disabled = true; }
    }
    function fileToVttUrl(file, done) { // a subtitle file chosen by the viewer: .srt or .vtt -> WebVTT blob
      var rd = new FileReader();
      rd.onload = function () {
        var text;
        try { text = new TextDecoder("utf-8", { fatal: true }).decode(rd.result); } catch (err) { text = new TextDecoder("windows-1252").decode(rd.result); }
        text = text.replace(/^\\uFEFF/, "").replace(/\\r\\n?/g, "\\n").trim();
