    }
    function buildSubs(v, di) {
      curVersion = v;
      Array.prototype.slice.call(video.querySelectorAll("track")).filter(function (t) { return t.getAttribute("data-local"); }).forEach(function (t) { t.remove(); });
      var subs = v.subs || [];
      extra.forEach(function (x) {
        var t = document.createElement("track");
        t.kind = "subtitles"; t.src = x.url; t.label = x.label; t.setAttribute("data-local", "1");
        video.appendChild(t);
      });
      subBar.textContent = "";
      subBar.appendChild(el("span", "nf-sublab", "Subtitles:"));
      function mk(label, i) {
        var b = el("button", "nf-pill", label); b.type = "button"; b.setAttribute("data-i", String(i));
        b.addEventListener("click", function () { showSub(i); });
        subBar.appendChild(b);
      }
      if (subs.length || extra.length) {
        mk("Off", -1);
        subs.forEach(function (s, i) { var L = languages.filter(function (l) { return l.code === s.lang; })[0]; mk(L ? L.label : s.lang, i); });
        extra.forEach(function (x, j) { mk(x.label, subs.length + j); });
      } else subBar.appendChild(el("span", "nf-sublab", "none available"));
      var add = el("button", "nf-pill", "Add file\\u2026"); add.type = "button";
      add.addEventListener("click", function () { pick.click(); });
      subBar.appendChild(add); subBar.appendChild(pick);
      showSub(di);
    }
    pick.addEventListener("change", function () {
      var f = pick.files && pick.files[0]; pick.value = "";
      if (!f) return;
      fileToVttUrl(f, function (url) {
        extra.push({ url: url, label: f.name.replace(/\\.[^.]+$/, "") });
        buildSubs(curVersion, (curVersion.subs || []).length + extra.length - 1);
      });
    });

    function setLang(code, keep) {
      var v = entry.versions[code], t = video.currentTime, playing = !video.paused;
      video.poster = v.poster || "";
      buildSubs(v, applySubs(video, v, code, markBad));
