    }
    if (avail.length > 1) {
      avail.forEach(function (l) {
        var b = el("button", "nf-pill", l.label);
        b.type = "button"; b.dataset.c = l.code;
        b.addEventListener("click", function () { setLang(l.code, true); });
        pills.appendChild(b);
      });
      foot.appendChild(pills);
    }
    foot.appendChild(subBar);
    dlg.appendChild(close); dlg.appendChild(video); dlg.appendChild(foot);
    modal.appendChild(dlg);
    document.body.appendChild(modal);
    var prevOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    setLang(current, false);
    close.focus();

    function done() {
      video.pause(); video.removeAttribute("src"); video.load();
      modal.remove();
